hospitals={r['hospital_id']:r for r in read_csv('hospitals.csv')}
days=read_csv('planning_days.csv')
day_index={r['day_id']:int(r['day_index']) for r in days}
days_sorted=sorted(day_index, key=lambda d: day_index[d])
cap={(r['day_id'],r['hospital_id']):r for r in read_csv('hospital_day_capacity.csv') if int(r['wave'])==current_wave}
panel_cap={(r['day_id'],r['recipient_hospital_id'],r['crossmatch_panel']):r for r in read_csv('crossmatch_panel_capacity.csv') if int(r['wave'])==current_wave}
bridge_cap={(r['day_id'],r['region']):r for r in read_csv('chain_bridge_capacity.csv') if int(r['wave'])==current_wave}
blackouts={(r['day_id'],r['donor_hospital_id'],r['recipient_region']) for r in read_csv('courier_blackouts.csv') if r.get('wave') and int(r['wave'])==current_wave}
policy={r['region']:r for r in read_csv('region_policy.csv') if int(r['wave'])==current_wave}
threshold=float(config['sensitized_cpra_threshold'])

edge_map={(e['donor_id'], e['recipient_pair_id']):e for e in edges}
out=defaultdict(list)
for e in edges:
    out[e['donor_id']].append(e['recipient_pair_id'])


def edge_day_feasible(donor_id, recip_id, day):
    e=edge_map.get((donor_id, recip_id))
    if not e: return False
    recip=pairs[recip_id]
    if day_index[day] < day_index[recip['earliest_surgery_day']]:
        return False
    if donor_id.startswith('P'):
        donor_pair=pairs[donor_id]
        if day_index[day] < day_index[donor_pair['earliest_surgery_day']]:
            return False
    else:
        alt=altruists[donor_id]
        if day_index[day] < day_index[alt['first_available_day']]:
            return False
    if float(e['travel_hours']) > float(recip['max_courier_hours']) + 1e-9:
        return False
    if int(e['late_courier_required']) and int(hospitals[e['donor_hospital_id']]['late_courier_ok'])==0:
        return False
    if (day, e['donor_hospital_id'], e['recipient_region']) in blackouts:
        return False
    return True


def pair_bonus(pid):
    p=pairs[pid]
    bonus=0.15*float(p['waiting_months'])
    if int(p['pediatric']): bonus += 12.0
    if p['priority_tier']=='urgent': bonus += 18.0
    elif p['priority_tier']=='high': bonus += 10.0
    if float(p['cpra']) >= threshold: bonus += 6.0
    return bonus


def link_score(donor_id, recip_id):
    e=edge_map[(donor_id, recip_id)]
    s=float(e['clinical_value'])
    s += 12.0*float(e['virtual_crossmatch_score'])
    s -= 38.0*float(e['failure_probability'])
    s -= 1.4*float(e['travel_hours'])
    s -= 5.0*int(e['late_courier_required'])
    s -= 1.75*int(e['lab_review_required'])
    return s

