seen2=set()
for i in sorted(pairs):
    for j in out.get(i,[]):
        if j in pairs and i<j and (j,i) in edge_map:
            cyc=[i,j]
            for d in days_sorted:
                if all(edge_day_feasible(cyc[k], cyc[(k+1)%2], d) for k in range(2)):
                    score=sum(link_score(cyc[k], cyc[(k+1)%2]) + pair_bonus(cyc[(k+1)%2]) for k in range(2))
                    cands.append({'kind':'cycle','pairs':cyc,'days':[d,d],'score':score,'altruist':None})
# cycles3
seen3=set()
