regions=sorted(policy)
model=Model()
model.hideOutput(True)
model.setParam('limits/gap', 0.0005)
model.setParam('limits/time', 30)
vars=[model.addVar(vtype='B', name=f'x{i}') for i in range(len(cands))]
for pid in pairs:
    idx=[i for i,c in enumerate(cands) if pid in c['pairs']]
    if idx:
        model.addCons(quicksum(vars[i] for i in idx) <= 1)
for a in altruists:
    idx=[i for i,c in enumerate(cands) if c['kind']=='chain' and c['altruist']==a]
    if idx:
        model.addCons(quicksum(vars[i] for i in idx) <= 1)
model.addCons(quicksum(vars[i] for i,c in enumerate(cands) if c['kind']=='chain') <= int(config['max_active_chain_starts']))
# caps
for d in days_sorted:
    for h in hospitals:
        # recipient
        expr=[]
        for i,c in enumerate(cands):
            cnt=sum(1 for pid,day in zip(c['pairs'], c['days']) if day==d and pairs[pid]['hospital_id']==h)
            if cnt: expr.append(cnt*vars[i])
        model.addCons(quicksum(expr) <= int(cap[(d,h)]['recipient_transplant_slots']))
        # lab slots incoming links
        expr=[]
        for i,c in enumerate(cands):
            cnt=0
            if c['kind']=='cycle':
                cyc=c['pairs']
                for k,pid in enumerate(cyc):
                    e=edge_map[(cyc[k-1], pid)]
                    if c['days'][k]==d and pid in pairs and pairs[pid]['hospital_id']==h and int(e['lab_review_required']):
                        cnt+=1
            else:
                for k,pid in enumerate(c['pairs']):
                    donor=c['altruist'] if k==0 else c['pairs'][k-1]
                    e=edge_map[(donor,pid)]
                    if c['days'][k]==d and pairs[pid]['hospital_id']==h and int(e['lab_review_required']): cnt+=1
            if cnt: expr.append(cnt*vars[i])
        model.addCons(quicksum(expr) <= int(cap[(d,h)]['lab_review_slots']))
        # retrieval
        expr=[]
        for i,c in enumerate(cands):
            cnt=0
            if c['kind']=='cycle':
                cyc=c['pairs']
                day=c['days'][0]
                if day==d:
                    cnt=sum(1 for pid in cyc if pairs[pid]['hospital_id']==h)
            else:
                # altruist retrieval at day1, then pair k retrieval at day k+1
                arow=altruists[c['altruist']]
                if c['days'][0]==d and arow['hospital_id']==h: cnt+=1
                for k,pid in enumerate(c['pairs'][:-1]):
                    if c['days'][k+1]==d and pairs[pid]['hospital_id']==h: cnt+=1
            if cnt: expr.append(cnt*vars[i])
        model.addCons(quicksum(expr) <= int(cap[(d,h)]['donor_retrieval_slots']))
        # panels
        for panel in ['single_antigen','flow_cytometry','desensitization']:
            pkey=(d,h,panel)
            if pkey not in panel_cap: continue
            expr=[]
            expr_hi=[]
            for i,c in enumerate(cands):
                cnt=0; cnt_hi=0
                if c['kind']=='cycle':
                    cyc=c['pairs']
                    for k,pid in enumerate(cyc):
                        e=edge_map[(cyc[k-1], pid)]
                        if c['days'][k]==d and pairs[pid]['hospital_id']==h and int(e['lab_review_required']) and e['crossmatch_panel']==panel:
                            cnt += 1
                            if float(pairs[pid]['cpra']) >= threshold: cnt_hi += 1
                else:
