                        e=edge_map[(donor,pid)]
                        if c['days'][k]==d and pairs[pid]['hospital_id']==h and int(e['lab_review_required']) and e['crossmatch_panel']==panel:
                            cnt += 1
                            if float(pairs[pid]['cpra']) >= threshold: cnt_hi += 1
                if cnt: expr.append(cnt*vars[i])
                if cnt_hi: expr_hi.append(cnt_hi*vars[i])
            model.addCons(quicksum(expr) <= int(panel_cap[pkey]['max_reviews']))
            model.addCons(quicksum(expr_hi) <= int(panel_cap[pkey]['high_cpra_review_limit']))
    for region in regions:
        bkey=(d,region)
