model.setObjective(quicksum(cands[i]['score']*vars[i] for i in range(len(cands))), 'maximize')
model.optimize()
print('status', model.getStatus())
sol=model.getBestSol()
sel=[i for i,v in enumerate(vars) if sol is not None and model.getSolVal(sol,v) > 0.5]
print('selected', len(sel), 'obj', model.getObjVal() if sol is not None else None)
for i in sel:
    c=cands[i]
    print(i, c['kind'], c['altruist'], list(zip(c['pairs'], c['days'])), round(c['score'],2))
