            def rec(pos, prev_day=None, cur=[]):
                if pos==len(path):
                    # build cand
                    score=float(altruists[a]['chain_start_value'])
                    # recipient bonuses
                    for pid in path:
                        score += pair_bonus(pid)
                    # links
                    donors=[a]+path[:-1]
                    for donor,pid in zip(donors,path):
                        score += link_score(donor,pid)
                    # bridge penalties only on gaps
                    for k in range(1,len(path)):
                        if day_index[cur[k]]>day_index[cur[k-1]]:
                            score -= float(pairs[path[k-1]]['bridge_penalty'])
                    cands.append({'kind':'chain','pairs':path[:],'days':cur[:],'score':score,'altruist':a})
                    return
                donor = a if pos==0 else path[pos-1]
                recip = path[pos]
                for d in days_sorted:
                    if prev_day is not None:
                        if day_index[d] < day_index[prev_day]:
                            continue
                        if day_index[d] - day_index[prev_day] > 1:
                            continue
                    if edge_day_feasible(donor, recip, d):
                        rec(pos+1, d, cur+[d])
            rec(0)
        if len(path)==config['max_chain_length']:
            return
        node = a if not path else path[-1]
        for nxt in out.get(node,[]):
            if nxt in path or nxt not in pairs:
                continue
            dfs(path+[nxt])
    dfs([])

